// kp1, the compact key transport (docs/10 §2.2): one 1.0 or 1.1 key object
// as a short canonical string, "kp1." + base64url(payload ‖ check), where
// check is the first 3 bytes of SHA-256(payload).  Written from the
// specification; tests/kp1.test.js checks it against fixtures generated by
// KeyPath's reference implementation (every golden string, every reject
// vector, and every key in the site's fixtures).
//
// Raw functions: payload(key) builds the bytes, text(bytes) the string, and
// parse(s) reads a string back (every unpack check but the last, then
// validateKey).  None calls pack or unpack, and none calls another raw one.
//   unpack(s) = parse(s), then require text(payload(parse(s))) === s
//   pack(key) = validateKey(key); s = text(payload(key)); then require
//               dumpsKey(parse(s)) === dumpsKey(key)
// Every failure is a KeyError.  kp1 accepts exactly what validateKey
// accepts: decode's own checks (hop registration, the chain's start at the
// source language, the edition's table list) are not kp1's, so an unpacked
// key may still be refused by decode, as key JSON may.
//
// Integers: every varint and the unit word 2·len + has_index (up to 2^32-1)
// are read and written with arithmetic, never with 32-bit bit operators.
import { KeyError, has, splitRoute, HOP_PREFIX, validateKey } from "./keycheck.js";
import { dumpsKey } from "./dumps.js";
import { sha256 } from "./sha256.js";

export const KP1_PREFIX = "kp1.";
const FORMAT = 0x01;
const CHECK_BYTES = 3;
const EDITION_BYTES = 6;
const UV_MAX = 2 ** 32 - 1;          // every varint, and the unit word
const LEN_MAX = 2 ** 31 - 1;         // a unit's len, so 2·len + 1 fits a varint
const FLAG_INLINE = 1, FLAG_HINT = 2;
const TAG_LITERAL = 1, TAG_RECORDS_FIRST = 8;
const RECORD_FIELD = { 1: "translation", 2: "translations" };
const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";

const fail = msg => { throw new KeyError(msg); };
const show = v => JSON.stringify(v);
const utf8Encoder = new TextEncoder();
// fatal: reject ill-formed UTF-8; ignoreBOM: a leading U+FEFF is text, kept
const utf8Decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });
const isInt = v => typeof v === "number" && Number.isInteger(v);
const wellFormed = s => (typeof s.isWellFormed === "function" ? s.isWellFormed() : !/\p{Cs}/u.test(s));

/** Trim ASCII whitespace only (TAB, LF, FF, CR, SPACE), as callers do before unpack. */
export const trimAscii = s => s.replace(/^[\t\n\f\r ]+|[\t\n\f\r ]+$/g, "");

// ------------------------------------------------------------ base64url

function b64urlEncode(bytes) {
  let out = "", acc = 0, bits = 0;
  for (const b of bytes) {
    acc = acc * 256 + b;
    bits += 8;
    while (bits >= 6) {
      bits -= 6;
      const d = 2 ** bits;
      out += B64[Math.floor(acc / d)];
      acc %= d;
    }
  }
  if (bits > 0) out += B64[acc * 2 ** (6 - bits)];
  return out;
}

/** Canonical base64url only: its alphabet, no padding, no length ≡ 1 (mod 4), zero unused bits. */
function b64urlDecode(body) {
  if (body.length % 4 === 1) fail("not canonical base64url (its length leaves a lone character)");
  const out = new Uint8Array(Math.floor(body.length * 3 / 4));
  let acc = 0, bits = 0, n = 0;
  for (const ch of body) {
    const v = ch.length === 1 ? B64.indexOf(ch) : -1;
    if (v < 0) fail(`not canonical base64url (${show(ch)} is outside A-Z a-z 0-9 - _)`);
    acc = acc * 64 + v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      const d = 2 ** bits;
      out[n++] = Math.floor(acc / d);
      acc %= d;
    }
  }
  if (acc !== 0) fail("not canonical base64url (non-zero unused bits in the last character)");
  return out;
}

// ------------------------------------------------------------ writer

class Writer {
  constructor() { this.out = []; }
  u8(b) { this.out.push(b); }
  uv(v, what) {
    if (!isInt(v) || v < 0 || v > UV_MAX) fail(`no kp1 form: ${what} ${show(v)} is not an integer in 0…2^32-1`);
    do {
      const b = v % 128;
      v = Math.floor(v / 128);
      this.out.push(v > 0 ? b + 128 : b);
    } while (v > 0);
  }
  str(s, what) {
    if (typeof s !== "string") fail(`no kp1 form: ${what} is not a string`);
    if (!wellFormed(s)) fail(`no kp1 form: ${what} has a lone surrogate, so no UTF-8 form`);
    const bytes = utf8Encoder.encode(s);
    this.uv(bytes.length, `${what} length`);
    for (const b of bytes) this.out.push(b);
  }
}

function hopSources(seg, si, R) {
  const [hops] = splitRoute(seg.route);
  const sources = [];
  let prev = null;
  hops.forEach((hop, i) => {
    const pair = hop.slice(HOP_PREFIX.length).split(">");
    if (pair.length !== 2) fail(`no kp1 form: segment ${si}: hop ${show(hop)} is not source>target`);
    const [a, b] = pair;
    if (i > 0 && a !== prev) fail(`no kp1 form: segment ${si}: the hop chain is not connected at ${show(hop)}`);
    const ordinal = R.kp1Languages.indexOf(a);
    if (ordinal < 0) fail(`no kp1 form: segment ${si}: hop source ${show(a)} is not a registered language`);
    sources.push(ordinal);
    prev = b;
  });
  if (hops.length && prev !== seg.language) fail(`no kp1 form: segment ${si}: the hops do not end at ${show(seg.language)}`);
  return sources;
}

function writeRecord(w, rec, where) {
  if (!rec || typeof rec !== "object" || Array.isArray(rec)) fail(`no kp1 form: ${where} is not a record`);
  const tier = rec.tier;
  if (tier === 1) {
    w.uv(1, `${where} tier`);
    w.uv(rec.index, `${where} index`);
  } else if (tier === 2) {
    w.uv(2, `${where} tier`);
    w.str(rec.engine, `${where} engine`);
    if (!Array.isArray(rec.patch)) fail(`no kp1 form: ${where} patch is not a list`);
    w.uv(rec.patch.length, `${where} patch length`);
    rec.patch.forEach((span, i) => {
      if (!Array.isArray(span) || span.length !== 3) fail(`no kp1 form: ${where} patch span ${i} is not [start, end, text]`);
      w.uv(span[0], `${where} patch span ${i} start`);
      w.uv(span[1], `${where} patch span ${i} end`);
      w.str(span[2], `${where} patch span ${i} text`);
    });
  } else if (tier === 3) {
    w.uv(3, `${where} tier`);
    w.str(rec.text, `${where} text`);
  } else fail(`no kp1 form: ${where} tier ${show(tier)}`);
}

function writeWord(w, word, where) {
  if (!word || typeof word !== "object" || Array.isArray(word)) fail(`no kp1 form: ${where} is not an object`);
  const names = Object.keys(word);
  const body = has(word, "units") ? "units" : has(word, "literal") ? "literal" : null;
  if (!body) fail(`no kp1 form: ${where} has neither units nor literal`);
  const records = has(word, "translation") ? "translation" : has(word, "translations") ? "translations" : null;
  const form = records === "translation" ? 1 : records ? 2 : 0;
  const first = records !== null && names.indexOf(records) < names.indexOf(body);
  w.u8((body === "literal" ? TAG_LITERAL : 0) + form * 2 + (first ? TAG_RECORDS_FIRST : 0));
  if (body === "literal") {
    const lit = word.literal;
    if (!lit || typeof lit !== "object") fail(`no kp1 form: ${where} literal is not an object`);
    w.str(lit.text, `${where} literal text`);
  } else {
    if (!Array.isArray(word.units)) fail(`no kp1 form: ${where} units is not a list`);
    w.uv(word.units.length, `${where} unit count`);
    word.units.forEach((unit, i) => {
      if (!unit || typeof unit !== "object") fail(`no kp1 form: ${where} unit ${i} is not an object`);
      if (!isInt(unit.len) || unit.len < 0 || unit.len > LEN_MAX)
        fail(`no kp1 form: ${where} unit ${i} len ${show(unit.len)} is not an integer in 0…2^31-1`);
      const hasIndex = has(unit, "homophone_index");
      w.uv(2 * unit.len + (hasIndex ? 1 : 0), `${where} unit ${i}`);
      if (hasIndex) w.uv(unit.homophone_index, `${where} unit ${i} homophone_index`);
    });
  }
  if (form === 1) writeRecord(w, word.translation, `${where} translation`);
  if (form === 2) {
    const list = word.translations;
    if (!Array.isArray(list) || list.length === 0) fail(`no kp1 form: ${where} translations is not a non-empty list`);
    w.uv(list.length, `${where} record count`);
    list.forEach((rec, i) => writeRecord(w, rec, `${where} translations[${i}]`));
  }
}

/** payload(K): the byte layout of docs/10 §2.2 from K's fields (Uint8Array). */
export function payload(key, R) {
  const w = new Writer();
  w.u8(FORMAT);
  const version = key.keypath === "1.0" ? 0 : key.keypath === "1.1" ? 1 : null;
  if (version === null) fail(`no kp1 form: key version ${show(key.keypath)}`);
  w.uv(version, "version");
  const digest = key.tables_sha256;
  if (typeof digest !== "string" || !/^[0-9a-fA-F]{64}$/.test(digest)) fail(`no kp1 form: tables_sha256 ${show(digest)} is not a sha256`);
  for (let i = 0; i < EDITION_BYTES; i++) w.u8(parseInt(digest.slice(2 * i, 2 * i + 2), 16));
  const source = R.kp1Languages.indexOf(key.source_language);
  if (source < 0) fail(`no kp1 form: source language ${show(key.source_language)} is not registered`);
  w.uv(source, "source language");
  if (!Array.isArray(key.segments)) fail("no kp1 form: segments is not a list");
  w.uv(key.segments.length, "segment count");
  key.segments.forEach((seg, si) => {
    const surface = R.kp1Surfaces.findIndex(([l, y]) => l === seg.language && y === seg.layout);
    if (surface < 0) fail(`no kp1 form: segment ${si}: (${seg.language}, ${seg.layout}) is not a registered surface`);
    w.uv(surface, `segment ${si} surface`);
    const sources = hopSources(seg, si, R);
    w.uv(sources.length, `segment ${si} hop count`);
    for (const s of sources) w.uv(s, `segment ${si} hop source`);
    const hint = has(seg, "hint");
    w.u8((seg.selector_mode === "inline" ? FLAG_INLINE : 0) + (hint ? FLAG_HINT : 0));
    if (hint) w.str(seg.hint, `segment ${si} hint`);
    if (!Array.isArray(seg.words)) fail(`no kp1 form: segment ${si} words is not a list`);
    w.uv(seg.words.length, `segment ${si} word count`);
    seg.words.forEach((word, wi) => writeWord(w, word, `segment ${si} word ${wi}`));
  });
  return Uint8Array.from(w.out);
}

/** text(p) = "kp1." + base64url(p ‖ the first 3 bytes of SHA-256(p)). */
export function text(bytes) {
  const all = new Uint8Array(bytes.length + CHECK_BYTES);
  all.set(bytes);
  all.set(sha256(bytes).subarray(0, CHECK_BYTES), bytes.length);
  return KP1_PREFIX + b64urlEncode(all);
}

// ------------------------------------------------------------ reader

class Reader {
  constructor(bytes) { this.b = bytes; this.i = 0; }
  get left() { return this.b.length - this.i; }
  u8(what) {
    if (this.i >= this.b.length) fail(`truncated: ${what}`);
    return this.b[this.i++];
  }
  uv(what) {
    let v = 0;
    for (let k = 0; k < 5; k++) {
      if (this.i >= this.b.length) fail(`truncated varint: ${what}`);
      const b = this.b[this.i++];
      if (k === 4 && b > 0x0f) fail(`varint out of range (5th byte ${b}): ${what}`);
      v += (b % 128) * 2 ** (7 * k);
      if (b < 128) {
        if (k > 0 && b === 0) fail(`non-minimal varint: ${what}`);
        return v;
      }
    }
    return fail(`varint out of range: ${what}`); // unreachable: a 5th byte ≤ 0x0F ends it
  }
  /** A count n of items (or bytes) still to read: never more than the bytes left. */
  count(what) {
    const n = this.uv(what);
    if (n > this.left) fail(`${what} ${n} exceeds the ${this.left} bytes remaining`);
    return n;
  }
  str(what) {
    const n = this.count(`${what} length`);
    const bytes = this.b.subarray(this.i, this.i + n);
    this.i += n;
    let s;
    try { s = utf8Decoder.decode(bytes); } catch { s = null; }
    if (s === null) fail(`${what} is not valid UTF-8`);
    return s;
  }
}

const hex = bytes => Array.from(bytes, b => b.toString(16).padStart(2, "0")).join("");

function readRecord(r, where) {
  const tier = r.uv(`${where} tier`);
  if (tier === 1) return { tier, index: r.uv(`${where} index`) };
  if (tier === 2) {
    const engine = r.str(`${where} engine`);
    const n = r.count(`${where} patch span count`);
    const patch = [];
    for (let i = 0; i < n; i++) patch.push([r.uv(`${where} span start`), r.uv(`${where} span end`), r.str(`${where} span text`)]);
    return { tier, engine, patch };
  }
  if (tier === 3) return { tier, text: r.str(`${where} text`) };
  return fail(`${where}: unknown tier ${tier}`);
}

function readWord(r, where) {
  const tag = r.u8(`${where} tag`);
  if (tag >= 16) fail(`${where}: reserved tag bits set (${tag})`);
  const literal = tag % 2 === 1;
  const form = Math.floor(tag / 2) % 4;
  const first = tag >= TAG_RECORDS_FIRST;
  if (form === 3) fail(`${where}: records form 3`);
  if (first && form === 0) fail(`${where}: records-first bit without records`);
  let body;
  if (literal) body = ["literal", { tier: 3, text: r.str(`${where} literal`) }];
  else {
    const n = r.count(`${where} unit count`);
    const units = [];
    for (let i = 0; i < n; i++) {
      const x = r.uv(`${where} unit ${i}`);
      const unit = { len: Math.floor(x / 2) };
      if (x % 2 === 1) unit.homophone_index = r.uv(`${where} unit ${i} homophone_index`);
      units.push(unit);
    }
    body = ["units", units];
  }
  let records = null;
  if (form === 1) records = [RECORD_FIELD[1], readRecord(r, `${where} translation`)];
  if (form === 2) {
    const n = r.count(`${where} record count`);
    if (n === 0) fail(`${where}: translations with no record`);
    const list = [];
    for (let i = 0; i < n; i++) list.push(readRecord(r, `${where} translations[${i}]`));
    records = [RECORD_FIELD[2], list];
  }
  const word = {};
  for (const [name, value] of records && first ? [records, body] : records ? [body, records] : [body]) word[name] = value;
  return word;
}

function readPayload(bytes, accepted, R) {
  const r = new Reader(bytes);
  const format = r.u8("format");
  if (format !== FORMAT) fail(`format ${format} (only 1 is defined)`);
  const version = r.uv("version");
  if (version > 1) fail(`key version code ${version} (0 is "1.0", 1 is "1.1")`);
  if (r.left < EDITION_BYTES) fail("truncated: edition");
  const prefix = hex(r.b.subarray(r.i, r.i + EDITION_BYTES));
  r.i += EDITION_BYTES;
  const editions = [...new Set(accepted.map(d => String(d).toLowerCase()))].filter(d => d.startsWith(prefix));
  if (editions.length === 0) fail(`edition prefix ${prefix} matches no accepted edition`);
  if (editions.length > 1) fail(`edition prefix ${prefix} matches ${editions.length} accepted editions: ${editions.join(", ")}`);
  const language = what => {
    const o = r.uv(what);
    if (o >= R.kp1Languages.length) fail(`${what}: language ordinal ${o} is not registered`);
    return R.kp1Languages[o];
  };
  const source = language("source language");
  const nseg = r.count("segment count");
  const segments = [];
  for (let si = 0; si < nseg; si++) {
    const o = r.uv(`segment ${si} surface`);
    if (o >= R.kp1Surfaces.length) fail(`segment ${si}: surface ordinal ${o} is not registered`);
    const [lang, layout] = R.kp1Surfaces[o];
    const nhops = r.count(`segment ${si} hop count`);
    const sources = [];
    for (let h = 0; h < nhops; h++) sources.push(language(`segment ${si} hop ${h} source`));
    const route = sources.map((s, h) => `${HOP_PREFIX}${s}>${h + 1 < sources.length ? sources[h + 1] : lang}`);
    route.push(...R.surfaces[lang][layout].routeTail);
    const flags = r.u8(`segment ${si} flags`);
    if (flags >= 4) fail(`segment ${si}: reserved flag bits set (${flags})`);
    const hint = flags >= FLAG_HINT ? r.str(`segment ${si} hint`) : null;
    const nwords = r.count(`segment ${si} word count`);
    const words = [];
    for (let wi = 0; wi < nwords; wi++) words.push(readWord(r, `segment ${si} word ${wi}`));
    const seg = { language: lang, layout, route, selector_mode: flags % 2 === 1 ? "inline" : "keyed", words };
    if (hint !== null) seg.hint = hint;
    segments.push(seg);
  }
  if (r.left) fail(`${r.left} trailing bytes after the last segment`);
  return { keypath: version === 1 ? "1.1" : "1.0", tables_sha256: editions[0], source_language: source, segments };
}

/**
 * parse(s): every unpack check except the canonical one, then validateKey.
 * `accepted` is the list of accepted edition digests (default: the page's
 * known editions).
 */
export function parse(s, R, accepted = R.editionHashes) {
  if (typeof s !== "string") fail("a kp1 key is text");
  if (!s.startsWith(KP1_PREFIX)) fail(`it does not start with ${show(KP1_PREFIX)} (lowercase)`);
  const data = b64urlDecode(s.slice(KP1_PREFIX.length));
  if (data.length < 1 + CHECK_BYTES) fail(`it decodes to ${data.length} bytes, fewer than 4`);
  const body = data.subarray(0, data.length - CHECK_BYTES);
  const check = sha256(body);
  for (let i = 0; i < CHECK_BYTES; i++)
    if (check[i] !== data[body.length + i]) fail("its check does not match (the text is damaged or mistyped)");
  const key = readPayload(body, accepted, R);
  validateKey(key, R);
  return key;
}

/** unpack(s): the key a kp1 string carries.  Needs no table and no ciphertext. */
export function unpack(s, R, accepted = R.editionHashes) {
  const key = parse(s, R, accepted);
  if (text(payload(key, R)) !== s) fail("its payload is not in canonical form");
  return key;
}

/** pack(K): the kp1 string of a key, defined only for keys that survive the round trip. */
export function pack(key, R, accepted = R.editionHashes) {
  validateKey(key, R);
  const s = text(payload(key, R));
  if (dumpsKey(parse(s, R, accepted)) !== dumpsKey(key))
    fail("no kp1 form: the key does not survive the round trip (an extra field, another field order, an uppercase digest, …)");
  return s;
}
